    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(amount > 0 && amount <= type(uint128).max, "bad amount");

        bool preclosed = c.closed();
        bool preReverted;
        try c.pre() { preReverted = false; } catch { preReverted = true; }

        bool success;
        if (preclosed || preReverted) {
            try c.openTake(UFixed18.wrap(amount)) { success = true; } catch { success = false; }
            assert(!success || false);
            return;
        }

        UFixed18 takerBefore = c.position(address(this)).taker;
        try c.openTake(UFixed18.wrap(amount)) { success = true; } catch { success = false; }

        UFixed18 takerAfter = c.position(address(this)).taker;
        assert(
            !success
                ? takerAfter.eq(takerBefore)
                : takerAfter.eq(takerBefore.add(UFixed18.wrap(amount)))
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(amount > 0 && amount <= type(uint128).max, "bad amount");

        bool preclosed = c.closed();

        UFixed18 takerBefore = c.position(address(this)).taker;

        bool success;
        try c.openTakeFor(address(this), UFixed18.wrap(amount)) {
            success = true;
        } catch {
            success = false;
        }

        UFixed18 takerAfter = c.position(address(this)).taker;
        bool postclosed = c.closed();

        assert(
            postclosed == preclosed &&
            (
                success
                    ? takerAfter.eq(takerBefore.add(UFixed18.wrap(amount)))
                    : takerAfter.eq(takerBefore)
            )
        );
    }

    receive() external payable {}
}
